'use strict';
(() => {
  const $ = id => document.getElementById(id);
  let storedTheme='light';
  try {storedTheme=localStorage.getItem('brandyar-theme')||'light';}catch{}
  if(document.documentElement)document.documentElement.dataset.theme=storedTheme;
  function updateThemeButton(){const dark=document.documentElement?.dataset.theme==='dark',toggle=$('theme-toggle');if(toggle){toggle.setAttribute?.('aria-pressed',String(dark));toggle.setAttribute?.('aria-label',dark?'فعال‌کردن حالت روشن':'فعال‌کردن حالت تاریک');const icon=toggle.querySelector?.('use');icon?.setAttribute('href',dark?'#sun':'#moon');}}
  updateThemeButton();
  $('theme-toggle')?.addEventListener('click',()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('brandyar-theme',theme);}catch{}updateThemeButton();});
  $('menu-toggle')?.addEventListener('click',()=>{const open=$('site-nav').classList.toggle('open');$('menu-toggle').setAttribute('aria-expanded',String(open));});
  if($('footer-year'))$('footer-year').textContent=new Intl.DateTimeFormat('fa-IR',{year:'numeric'}).format(new Date());
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const n = value => new Intl.NumberFormat('fa-IR').format(value);
  const date = value => new Intl.DateTimeFormat('fa-IR',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value*1000));
  const technical = value => `<details><summary>اطلاعات فنی این نسخه</summary><pre>${esc(JSON.stringify(value,null,2))}</pre></details>`;
  const admin = location.pathname.startsWith('/admin/');
  const endpoint = admin ? '/api/admin/personal-brand' : '/api/personal-brand';
  let bootstrap, current, step = 1, csrf, started = Date.now(), busy = false, skipping = false;
  let adminQuery = {};
  const dimensionTitle = key => ({identity:'وضوح هویت حرفه‌ای',position:'جایگاه‌یابی و مخاطب',credibility:'اعتبار تخصصی',message:'پیام و لحن',digital:'اجرای دیجیتال',growth:'رشد و تمایز',clarity:'روشن‌بودن مسیر',introduction:'قابل‌فهم‌بودن معرفی',evidence:'اعتماد و شواهد',content:'هماهنگی محتوا',visibility:'استمرار و دیده‌شدن'})[key] || 'بُعد';
  let questionTimes = {}, focusedQuestion = null;
  function finishFocus(){if(focusedQuestion){const {key,time}=focusedQuestion;questionTimes[key]=Math.min((questionTimes[key]||0)+Date.now()-time,86400000);focusedQuestion=null;}}
  document.addEventListener('focusin',event=>{if(step===3 && event.target.matches('#step-form select, #step-form input[type=radio]')){finishFocus();focusedQuestion={key:event.target.name,time:Date.now()};}});
  document.addEventListener('focusout',finishFocus);
  document.addEventListener('visibilitychange',()=>{if(document.hidden){finishFocus();flushDraft();}});
  const actions = html => `<div class="actions">${html}</div>`;
  const button = (action,title,id='') => {
    if(admin && bootstrap?.permissions && ((!bootstrap.permissions.private && action==='admin_open') || (!bootstrap.permissions.manage && ['template_edit','template_publish','template_inactive','feedback','model_edit','model_publish','archive','regenerate','disconnect_connection'].includes(action)))) return '';
    return `<button type="button" data-action="${action}" data-id="${esc(id)}">${esc(title)}</button>`;
  };
  async function api(query='', body) {
    const controller = new AbortController(), timer = setTimeout(()=>controller.abort(),95000);
    try {
      const response=await fetch(endpoint+query,{credentials:'same-origin',cache:'no-store',keepalive:body?.action==='draft',signal:controller.signal,...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...body,csrf})}:{})});
      const result=await response.json();
      if(!response.ok) throw new Error(result.error || 'عملیات انجام نشد؛ دوباره تلاش کنید.');
      return result.data;
    } catch(error) {
      if(['AbortError','SyntaxError','TypeError'].includes(error.name)) throw new Error('ارتباط برقرار نشد؛ دوباره تلاش کن.');
      throw error;
    } finally {clearTimeout(timer);}
  }
  function confirmAction(text) {
    $('confirm-text').textContent=text;$('confirm-check').checked=false;$('confirm-yes').disabled=true;$('confirm').returnValue='cancel';$('confirm').showModal();
    return new Promise(resolve=>$('confirm').addEventListener('close',()=>resolve($('confirm').returnValue==='yes' && $('confirm-check').checked),{once:true}));
  }
  $('confirm-check').addEventListener('change',()=>{$('confirm-yes').disabled=!$('confirm-check').checked;});
  function field(key,title,value='',required=false) {const short=key==='expertise';return `<label class="question-card">${esc(title)}${required?' *':''}${short?`<input name="${esc(key)}" value="${esc(value)}" maxlength="200" ${required?'required':''}>`:`<textarea name="${esc(key)}" maxlength="1200" ${required?'required':''}>${esc(value)}</textarea>`}<small data-count="${esc(key)}">${n(String(value).length)} از ${short?'۲۰۰':'۱۲۰۰'} نویسه</small></label>`;}
  function selection(key,title,options,saved,multiple=false){return `<fieldset class="question-card"><legend>${esc(title)} *</legend>${multiple?'<small>یک یا حداکثر دو گزینه انتخاب کنید.</small>':''}<div class="choice-grid">${options.map((v,i)=>`<label class="choice"><input type="${multiple?'checkbox':'radio'}" name="${esc(key)}" value="${esc(v)}" ${multiple?(Array.isArray(saved)&&saved.includes(v)?'checked':''):(saved===v?'checked':'')} ${multiple?'':'required'}><span>${esc(v)}</span></label>`).join('')}</div></fieldset>`;}
  let draftTimer, draftPending, draftQueue=Promise.resolve();
  function persistDraft(form) {
    if(!current||![3,4].includes(current.template.schema))return;
    const values=formValues(form);
    if(step===3)for(const key in values)values[key]=Number(values[key]);
    current.answers[String(step)]=values;
    try{localStorage.setItem('pb-draft-'+current.assessment.id+'-'+step,JSON.stringify(values));}catch{}
    const body={action:'draft',id:current.assessment.id,revision:current.assessment.revision,step,answers:values};
    clearTimeout(draftTimer);
    draftPending=body;
    draftTimer=setTimeout(()=>flushDraft(),600);
  }
  async function flushDraft() {
    clearTimeout(draftTimer);
    if(draftPending){const body=draftPending;draftPending=null;draftQueue=draftQueue.then(()=>api('',body)).then(()=>{if($('save-state'))$('save-state').textContent='پاسخ‌هایت ذخیره شده و می‌توانی بعداً ادامه بدهی.';}).catch(()=>{if($('save-state'))$('save-state').textContent='پاسخ‌هایت حفظ شده؛ وقتی ارتباط برقرار شد ادامه بده.';});}
    await draftQueue;
  }
  function formValues(form){
    const entries=[...new FormData(form)],values=Object.fromEntries(entries);
    if(form.id==='step-form'){
      if(step===1&&current?.template.barriers)values.barrier=entries.filter(([key])=>key==='barrier').map(([,v])=>v);
      if([3,4].includes(current?.template.schema)&&step===1)values.audience=entries.filter(([key])=>key==='audience').map(([,v])=>v);
      if([3,4].includes(current?.template.schema)&&step===4){const key=current.template.schema===4?'available_proof':'proof';values[key]=entries.filter(([name])=>name===key).map(([,v])=>v);}
    }
    return values;
  }
  async function load() {
    $('feedback').textContent='در حال آماده‌سازی ارزیابی…';
    bootstrap=await api(admin?'':'?action=bootstrap');csrf=bootstrap.csrf;
    if(!admin&&new URLSearchParams(location.search).get('instagram')==='connected'&&bootstrap.connection?.status==='connected'&&!bootstrap.connection.synced_at){try{await api('',{action:'sync'});bootstrap=await api('?action=bootstrap');}catch{}}
    if(admin){paintAdmin();}else{home();}
    $('feedback').textContent='';
  }
  function home() {
    current=null;
    const draft=bootstrap.assessments.find(r=>r.state==='draft'),done=bootstrap.assessments.find(r=>r.state==='completed');
    const outcome=new URLSearchParams(location.search).get('instagram');
    $('app').innerHTML=`${outcome==='connected'?'<p class="notice">اینستاگرامت متصل شد؛ می‌توانی ارزیابی را ادامه بدهی.</p>':outcome?'<p class="notice">اتصال انجام نشد؛ می‌توانی بدون اتصال ادامه بدهی.</p>':''}<section class="assessment-intro"><span class="eyebrow">ارزیابی پرسونال برند · پنج بخش کوتاه</span><h2>ببین پرسونال برندت الان کجای مسیر است</h2><p>با چند سؤال ساده، تصویری کلی از وضعیت فعلی‌ات می‌گیری و می‌فهمی از کجا بهتر است شروع کنی.</p><div class="intro-metrics"><span>حدود ۸ تا ۱۰ دقیقه</span><span>پنج بخش ساده</span><span>هر وقت خواستی ادامه بده</span></div>${draft?button('open','ادامهٔ ارزیابی',draft.id):done?button('open','دیدن نتیجه',done.id):button('start','شروع ارزیابی')}<p>${draft?'پاسخ‌هایت ذخیره شده و از همان‌جا ادامه می‌دهی.':done?'آخرین نتیجه‌ات آماده است.':'هنوز ارزیابی ثبت نکرده‌ای.'}</p></section>`;
  }
  function connectionPanel() {
    const c=bootstrap.connection;
    if(c?.status!=='connected')return '';
    return `<section><h2>صفحهٔ اینستاگرام تو</h2><p><bdi>${esc(c.username)}</bdi></p><p>می‌توانی هر زمان اتصال را قطع کنی؛ بعد از آن اطلاعات تازه‌ای دریافت نمی‌شود.</p>${actions(button('disconnect','قطع اتصال')+button('delete_instagram','پاک‌کردن اطلاعات اینستاگرام'))}</section>`;
  }
  function v3Selection(key,title,options,saved,multiple=false){return `<fieldset class="question-card"><legend>${esc(title)} *</legend>${multiple?(key==='audience'?'<small>حداکثر دو گزینه را انتخاب کن.</small>':'<small>می‌توانی چند گزینه را انتخاب کنی.</small>'):''}<div class="choice-grid">${options.map(v=>`<label class="choice"><input type="${multiple?'checkbox':'radio'}" name="${esc(key)}" value="${esc(v)}" ${multiple?(Array.isArray(saved)&&saved.includes(v)?'checked':''):(saved===v?'checked':'')} ${multiple?'':'required'}><span>${esc(v)}</span></label>`).join('')}</div></fieldset>`;}
  function v3Text(key,title,value=''){return `<label class="question-card" ${key.endsWith('_other')?`data-other-for="${key.replace('_other','')}"`:''}>${esc(title)}${key==='experience'?`<textarea name="${esc(key)}" maxlength="1200">${esc(value)}</textarea>`:`<input name="${esc(key)}" value="${esc(value)}" maxlength="200">`}</label>`;}
  function updateOtherFields(form){
    const values=formValues(form),other={field:'موضوع دیگری دارم',goal:'هدف دیگری دارم',audience:'گروه دیگری مدنظرم است',situation:'مورد دیگری دارم.'};
    for(const label of form.querySelectorAll('[data-other-for]')){const key=label.dataset.otherFor,visible=Array.isArray(values[key])?values[key].includes(other[key]):values[key]===other[key];label.hidden=!visible;const input=label.querySelector('input');if(input)input.required=key==='field'&&visible;}
  }
  function paintStep() {
    const t=current.template,id=current.assessment.id,saved={...(current.answers[String(step)]||{})};
    try{Object.assign(saved,JSON.parse(localStorage.getItem('pb-draft-'+id+'-'+step)||'{}'));}catch{}
    if(t.schema===4){paintV4Step();return;}
    if(t.schema!==3){paintLegacyStep();return;}
    const section=t.sections[step-1],remaining=step===3?15:Object.keys(step===1?t.base:step===2?t.image:step===4?t.evidence:t.online).length;
    let form='';
    if(step===1){form=t.base.map(([key,title,options])=>v3Selection(key,title,options,saved[key],key==='audience')).join('')+v3Text('field_other','اگر موضوع دیگری را انتخاب کردی، کوتاه بنویس.',saved.field_other)+v3Text('goal_other','اگر هدف دیگری داری، کوتاه بنویس.',saved.goal_other)+v3Text('audience_other','اگر گروه دیگری مدنظرت است، کوتاه بنویس.',saved.audience_other)+v3Text('situation_other','اگر مورد دیگری داری، کوتاه بنویس.',saved.situation_other);}
    else if(step===2){form=t.image.map(([key,title,options])=>v3Selection(key,title,options,saved[key])).join('');}
    else if(step===3){form=current.order.map(id=>t.behavior.find(q=>q.id===id)).filter(Boolean).map((q,i)=>`<fieldset class="question-card"><legend>${n(i+1)}. ${esc(q.title)}</legend><div class="likert">${t.likert.map((label,j)=>`<label class="choice"><input type="radio" name="${q.id}" value="${j+1}" ${Number(saved[q.id])===j+1?'checked':''} required><span>${esc(label)}</span></label>`).join('')}</div></fieldset>`).join('');}
    else if(step===4){form=v3Selection('proof',t.evidence[0][1],t.evidence[0][2],saved.proof,true)+v3Text('experience',t.evidence[1][1],saved.experience)+v3Selection('need',t.evidence[2][1],t.evidence[2][2],saved.need);}
    else {form=t.online.map(([key,title,options])=>v3Selection(key,title,options,saved[key])).join('')+`<section class="instagram-card"><h3>می‌خواهی نتیجه‌ات دقیق‌تر بررسی شود؟</h3><p>اگر در اینستاگرام فعالیت می‌کنی، می‌توانی صفحهٔ حرفه‌ای‌ات را متصل کنی تا نتیجهٔ ارزیابی با محتوای واقعی صفحه‌ات هم مقایسه شود.</p>${bootstrap.instagram_available?'<label><input id="consent" type="checkbox">با دریافت محتوای صفحهٔ حرفه‌ای‌ام برای مقایسه با پاسخ‌هایم موافقم. رمز عبورم دریافت نمی‌شود. <a href="/#/privacy">حریم خصوصی</a></label><div class="actions"><button type="button" class="secondary" data-action="oauth">اتصال اینستاگرام</button>':''}<button type="submit" name="skip" class="secondary">ادامه بدون اتصال</button>${bootstrap.instagram_available?'</div>':''}${bootstrap.connection?.status==='connected'&&bootstrap.connection.synced_at?'<button type="submit" name="connected">دیدن نتیجه با صفحهٔ متصل‌شده</button>':''}</section>`;}
    $('app').innerHTML=`<div class="stage-progress"><div><strong>بخش ${n(step)} از ۵</strong><span>حدود ${n(remaining)} سؤال در این بخش</span></div><progress max="5" value="${step}" aria-label="پیشرفت ارزیابی"></progress></div><nav class="step-navigation">${t.sections.map((v,i)=>`<span ${i+1===step?'aria-current="step"':''}>${n(i+1)}. ${esc(v.title)}</span>`).join(' · ')}</nav><section><h2 id="stage-heading" tabindex="-1">${esc(section.title)}</h2><p class="stage-description">${esc(section.description)}</p><p class="muted">هدف این بخش: ${esc(section.purpose)}</p><form id="step-form">${form}<div class="actions">${step>1?button('previous','بازگشت'):''}<button type="submit">${step===5?'دیدن نتیجهٔ اولیه':'ادامه'}</button></div></form><p id="save-state" role="status">پاسخ‌هایت ذخیره می‌شود.</p></section>`;started=Date.now();$('stage-heading')?.focus?.();updateOtherFields($('step-form'));
    if(step===5)$('app').insertAdjacentHTML('beforeend',connectionPanel());
    if(step===3)$('app').insertAdjacentHTML('beforeend',`<details class="question-feedback"><summary>یکی از سؤال‌ها برایت روشن نبود؟</summary><form id="question-feedback"><label>سؤال<select name="question_id">${t.behavior.map((q,i)=>`<option value="${q.id}">${n(i+1)}. ${esc(q.title)}</option>`).join('')}</select></label><label>وضوح سؤال<select name="clarity"><option value="1">برایم مبهم بود</option><option value="2">تا حدی روشن بود</option><option value="3">کاملاً روشن بود</option></select></label><button>ثبت بازخورد</button></form></details>`);
  }
  function v4Selection(key,title,options,saved,multiple=false){return `<fieldset class="question-card"><legend>${esc(title)} *</legend>${multiple?`<small>${key==='audience'?'حداکثر دو گزینه را انتخاب کن.':'می‌توانی چند گزینه را انتخاب کنی.'}</small>`:''}<div class="choice-grid">${options.map(value=>`<label class="choice"><input type="${multiple?'checkbox':'radio'}" name="${esc(key)}" value="${esc(value)}" ${multiple?(Array.isArray(saved)&&saved.includes(value)?'checked':''):(saved===value?'checked':'')} ${multiple?'':'required'}><span>${esc(value)}</span></label>`).join('')}</div></fieldset>`;}
  function v4Text(key,title,value='',placeholder=''){const other=key==='proud_work'?'':` data-other-for="${esc(key)}"`;return `<label class="question-card"${other}>${esc(title)}<input name="${esc(key)}" value="${esc(value)}" maxlength="${key==='proud_work'?'300':'200'}" placeholder="${esc(placeholder)}"></label>`;}
  function updateV4Other(form){const values=formValues(form),map=current.template.other;for(const label of form.querySelectorAll('[data-other-for]')){const key=label.dataset.otherFor,source=key.endsWith('_other')?key.slice(0,-6):key,chosen=values[source],visible=map[source]&&(Array.isArray(chosen)?chosen.includes(map[source]):chosen===map[source]);label.hidden=!visible;label.querySelector('input').disabled=!visible;}}
  function paintV4Step(){
    const t=current.template,id=current.assessment.id,saved={...(current.answers[String(step)]||{})};try{Object.assign(saved,JSON.parse(localStorage.getItem('pb-draft-'+id+'-'+step)||'{}'));}catch{}
    const section=t.sections[step-1],fields=step===1?t.base:step===2?t.image:step===4?t.evidence:t.online;let form='';
    if(step===1)form=fields.map(([key,title,options])=>v4Selection(key,title,options,saved[key],key==='audience')).join('')+v4Text('field_other','اگر دوست داری، موضوعت را بنویس.',saved.field_other)+v4Text('primary_goal_other','اگر دوست داری، هدفت را بنویس.',saved.primary_goal_other)+v4Text('audience_other','اگر دوست داری، گروهت را بنویس.',saved.audience_other)+v4Text('current_situation_other','اگر دوست داری، وضعیتت را بنویس.',saved.current_situation_other);
    else if(step===2)form=fields.map(([key,title,options])=>v4Selection(key,title,options,saved[key])).join('');
    else if(step===3)form=current.order.map(id=>t.behavior.find(q=>q.id===id)).map((q,index)=>`<fieldset class="question-card"><legend>${n(index+1)}. ${esc(q.title)}</legend><div class="likert">${t.likert.map((label,i)=>`<label class="choice"><input type="radio" name="${q.id}" value="${i+1}" ${Number(saved[q.id])===i+1?'checked':''} required><span>${esc(label)}</span></label>`).join('')}</div></fieldset>`).join('');
    else if(step===4)form=v4Selection('available_proof',fields[0][1],fields[0][2],saved.available_proof,true)+v4Text('proud_work',fields[1][1],saved.proud_work,'حتی یک تجربهٔ کوچک هم می‌تواند کافی باشد.')+v4Selection('evidence_need',fields[2][1],fields[2][2],saved.evidence_need);
    else form=fields.map(([key,title,options])=>v4Selection(key,title,options,saved[key])).join('');
    if(step!==3)form+=fields.filter(([key])=>t.other[key]&&step!==1).map(([key])=>v4Text(key+'_other','اگر دوست داری، کوتاه بنویس.',saved[key+'_other'])).join('');
    const remaining=step===3?15:fields.length;$('app').innerHTML=`<div class="stage-progress"><div><strong>بخش ${n(step)} از ۵</strong><span>حدود ${n(remaining)} سؤال در این بخش</span></div><progress max="5" value="${step}" aria-label="پیشرفت ارزیابی"></progress></div><nav class="step-navigation">${t.sections.map((value,index)=>`<span ${index+1===step?'aria-current="step"':''}>${n(index+1)}. ${esc(value.title)}</span>`).join(' · ')}</nav><section><h2 id="stage-heading" tabindex="-1">${esc(section.title)}</h2><p class="stage-description">${esc(section.description)}</p><form id="step-form">${form}<div class="actions">${button(step>1?'previous':'home','بازگشت')}<button type="submit">ادامه</button></div></form><p id="save-state" role="status">پاسخ‌هایت ذخیره می‌شود.</p></section>`;started=Date.now();updateV4Other($('step-form'));$('stage-heading')?.focus?.();
  }
  function paintLegacyStep(){
    const t=current.template,id=current.assessment.id,saved=current.answers[String(step)]||{},names=['وضعیت حرفه‌ای و هدف','هویت و جایگاه','رفتارهای برندسازی','شواهد اختیاری','اتصال اختیاری اینستاگرام'];
    let form='';if(step===1||step===2||step===4){const fields=step===1?t.base:step===2?t.identity:t.evidence.map(v=>[...v,false]);form=fields.map(([key,title,required])=>step===1&&t.statuses&&key==='professional_status'?selection(key,title,t.statuses,saved[key])+selection('goal','مهم‌ترین هدف شما از ساخت پرسونال برند چیست؟',t.goals,saved.goal):step===1&&t.barriers&&key==='barrier'?selection(key,title,t.barriers,saved[key],true):field(key,title,saved[key],required)).join('');if(step===1&&!t.statuses)form+=`<label>هدف اصلی برند *<select name="goal" required><option value="">انتخاب کنید</option>${t.goals.map(v=>`<option ${saved.goal===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;}else if(step===3){form=current.order.map(id=>t.items.find(q=>q.id===id)).map(q=>`<fieldset class="question-card"><legend>${esc(q.title)}</legend><div class="likert">${t.likert.map((label,i)=>`<label class="choice"><input type="radio" name="${q.id}" value="${i+1}" ${Number(saved[q.id])===i+1?'checked':''} required><span>${esc(label)}</span></label>`).join('')}</div></fieldset>`).join('');}else form='<p>اگر دوست داری، بدون اتصال ادامه بده.</p><button type="submit" name="skip">ادامه بدون اتصال</button>';
    $('app').innerHTML=`<section><h2>مرحلهٔ ${n(step)} از ۵</h2><form id="step-form">${form}<div class="actions">${step>1?button('previous','بازگشت'):''}<button type="submit">${step===5?'دیدن نتیجهٔ اولیه':'ادامه'}</button></div></form></section>`;
  }
  function instagramView(report){
    const ig=report.instagram;if(!ig)return '';
    return `<section><h2>هدفت و صفحه‌ای که دیده می‌شود</h2><p>هدف تو: ${esc(report.goal)}</p><p>معرفی صفحه: ${esc(ig.profile.biography||'متن معرفی در دسترس نبود.')}</p><p>بررسی ${n(ig.observations.sample_size)} محتوای دریافت‌شده در ${date(ig.synced_at)}</p><p>موضوع‌های تکرارشونده در هشتگ‌ها: ${ig.observations.hashtags.map(v=>esc(v[0])).join('، ')||'هشتگ تکرارشونده‌ای در این نمونه دیده نشد.'}</p><p>این موضوع‌ها چقدر همان چیزی را نشان می‌دهند که می‌خواهی با آن شناخته شوی؟ این داده‌ها به‌تنهایی هماهنگی معنایی یا کیفیت محتوا را تأیید نمی‌کنند.</p>${ig.synced_at<Date.now()/1000-86400?'<p>این تصویر مربوط به آخرین دریافت است و ممکن است صفحه‌ات بعد از آن تغییر کرده باشد.</p>':''}</section>`;
  }
  function reportView(report) {
    if(report.analysis_version==='monthly-behavior-v4'){
      try{localStorage.setItem('brandyar-test-completed','true')}catch{}
      return `<section class="result-hero"><p>گزارش شخصی تو</p><h2>امتیاز کلی: ${n(report.total)} از ۱۰۰</h2><p>مرحلهٔ فعلی: ${esc(report.stage)}</p><p>${esc(report.summary)}</p></section><div class="grid">${report.dimensions.map(d=>`<article class="card"><h3>${esc(d.title)}</h3><progress max="100" value="${d.score}" aria-label="${esc(d.title)}"></progress><p>${n(d.score)} از ۱۰۰</p></article>`).join('')}</div><section><h2>نقطهٔ قوت</h2><p>${esc(report.strength)}</p><h2>فرصت رشد</h2><p>${esc(report.top_opportunity)}</p><h2>اقدام ابتدایی</h2><p>${esc(report.starter_action)}</p><h2>سؤال برای ادامه</h2><p>${esc(report.challenge_question)}</p><p class="muted">${esc(report.disclaimer)}</p></section><section class="brandiyar-invite"><span class="eyebrow">قدم بعدی، اختیاری</span><h2>می‌خواهی این شناخت را به یک مسیر قابل‌استفاده تبدیل کنی؟</h2><p>در فضای خصوصی برندیـار می‌توانی هویت حرفه‌ای‌ات را تکمیل و برای ساخت محتوای هماهنگ آماده کنی.</p><a class="button" href="/brandyar/plans">مشاهدهٔ تعرفه‌های برندیـار</a></section>`;
    }
    if(report.top_opportunity){
      if(!current?.report_unlocked||!report.dimensions)return `<section class="result-hero"><p>نتیجهٔ اولیهٔ ارزیابی تو</p><h2>امتیاز فعلی پرسونال برندت: ${n(report.total)} از ۱۰۰</h2><p>مرحلهٔ فعلی: ${esc(report.stage)}</p><p>${esc(report.summary)}</p>${report.preview_opportunities?.length?`<p>فرصت‌های رشد: ${report.preview_opportunities.map(esc).join('، ')}</p>`:''}<p>این نتیجه یک تصویر کلی از وضعیت فعلی توست و قرار نیست ارزش یا توانایی‌ات را قضاوت کند.</p></section><section class="lead-card"><h2>گزارش کاملت آماده است</h2><p>شماره‌ات را وارد کن تا نتیجهٔ کامل، امتیاز بخش‌ها و تحلیل شخصی‌سازی‌شده‌ات را ببینی.</p><form id="lead-form"><label>شمارهٔ موبایل<input name="phone" type="tel" inputmode="tel" autocomplete="tel" maxlength="24" aria-describedby="lead-error" required></label><label class="consent"><input name="consent" type="checkbox" required>با ذخیرهٔ شماره برای نمایش این گزارش موافقم.</label><p id="lead-error" class="form-error" role="alert"></p><button type="submit">مشاهدهٔ نتیجهٔ کامل</button></form><button type="button" data-action="later">بعداً وارد می‌کنم</button></section>`;
      return `<section class="result-hero"><p>گزارش شخصی تو</p><h2>امتیاز فعلی تو: ${n(report.total)} از ۱۰۰</h2><p>مرحلهٔ فعلی: ${esc(report.stage)}</p><p>${esc(report.summary)}</p></section><section><h2>الان کجای مسیر هستی؟</h2><p>${esc(report.summary)}</p><p>${esc(report.limitations[0])}</p></section><div class="grid">${report.dimensions.map(d=>`<article class="card"><h3>${esc(d.title)}</h3><progress max="100" value="${d.score}" aria-label="${esc(d.title)}"></progress><p>${n(d.score)} از ۱۰۰ · ${esc(d.interpretation)}</p></article>`).join('')}</div><section><h2>مهم‌ترین نقطهٔ قوت</h2><p>${esc(report.strength)}</p><ul>${report.points.map(v=>`<li>${esc(v)}</li>`).join('')}</ul><h3>چرا این نتیجه را گرفتی؟</h3><p>${esc(report.reason)}</p><h2>مهم‌ترین فرصت رشد</h2><p>${esc(report.top_opportunity)}</p><p>${esc(report.starter_action)}</p><h3>یک سؤال برای ادامه</h3><p>${esc(report.challenge_question)}</p></section>${instagramView(report)}`;
    }
    if(!current?.report_unlocked||!report.dimensions){return `<section class="result-hero"><p class="result-kicker">نتیجهٔ اولیهٔ ارزیابی تو</p><h2>امتیاز فعلی پرسونال برندت: ${n(report.total)} از ۱۰۰</h2><p>مرحلهٔ فعلی: ${esc(report.stage)}</p><p>${esc(report.summary)}</p>${report.preview_opportunities?.length?`<p>فرصت‌های رشد: ${report.preview_opportunities.map(esc).join('، ')}</p>`:''}<p>این نتیجه یک تصویر کلی از وضعیت فعلی توست و قرار نیست ارزش یا توانایی‌ات را قضاوت کند.</p></section><section class="lead-card"><h2>گزارش کاملت آماده است</h2><p>شماره‌ات را وارد کن تا امتیاز بخش‌ها و تحلیل شخصی‌سازی‌شده‌ات را ببینی.</p><form id="lead-form"><label>شمارهٔ موبایل<input name="phone" type="tel" inputmode="tel" autocomplete="tel" required maxlength="14" placeholder="۰۹۱۲۱۲۳۴۵۶۷"></label><label class="consent"><input name="consent" type="checkbox" required>با ذخیرهٔ شماره برای نمایش این گزارش موافقم.</label><p id="lead-error" class="form-error" role="alert"></p><button type="submit">مشاهدهٔ نتیجهٔ کامل</button></form><button type="button" data-action="later">بعداً وارد می‌کنم</button></section>`;}
    if(!admin)return `<section class="result-hero"><h2>امتیاز فعلی تو: ${n(report.total)} از ۱۰۰</h2><p>مرحلهٔ فعلی: ${esc(report.stage)}</p><p>${esc(report.summary)}</p></section><section><h2>الان کجای مسیر هستی؟</h2><p>این نتیجه یک تصویر کلی از وضعیت فعلی توست و قرار نیست ارزش یا توانایی‌ات را قضاوت کند.</p><h3>نقطهٔ قوت فعلی</h3><p>${esc(report.strength)}</p><h3>فرصت رشد</h3><p>${esc(report.bottleneck)}</p>${report.dimensions.map(d=>`<p>${esc(d.title)}: ${n(d.score)} از ۱۰۰</p><progress max="100" value="${d.score}" aria-label="${esc(d.title)}"></progress>`).join('')}</section>`;
    const list=values=>`<ol>${values.map(v=>`<li>${esc(v.title)}<small>مبنای توصیه: پاسخ‌های بُعد ${esc(report.dimensions.find(d=>d.key===v.dimension)?.title||'')}.</small></li>`).join('')}</ol>`;
    const ig=report.instagram;
    return `<section class="result-hero"><p class="result-kicker">گزارش اختصاصی بر پایهٔ پاسخ‌های ذخیره‌شدهٔ شما</p><h2>نقشهٔ پرسونال برند شما</h2><p class="metric">مرحلهٔ احتمالی: ${esc(report.stage)}</p><p>سطح اطمینان: ${esc(report.confidence)}</p><p>قوت: ${esc(report.strength)} · گلوگاه: ${esc(report.bottleneck)}</p><p>${esc(report.pattern)}</p><p>زمان تحلیل: ${date(report.created_at)} · نسخهٔ نتیجه: ${n(report.version)}</p></section><section><h2>خلاصهٔ اجرایی</h2><p>${esc(report.summary||`حوزهٔ فعالیت: ${report.professional.expertise}. فرصت رشد: ${report.strength}؛ اولویت رسیدگی: ${report.bottleneck}.`)}</p><h3>الگوی اصلی و چرایی انتخاب</h3><p>${esc(report.pattern_reason||'الگوی راهنما بر پایهٔ پاسخ‌های این نسخهٔ ارزیابی.')}</p>${report.secondary_patterns?.length?`<p>الگوهای فرعی: ${report.secondary_patterns.map(esc).join('، ')}</p>`:''}</section><div class="grid">${report.dimensions.map(d=>`<article class="card"><h3>${esc(d.title)}</h3><p>${esc(d.description)}</p><progress max="100" value="${d.score}" aria-label="${esc(d.title)}"></progress><p>${n(d.score)} از ۱۰۰ · ${esc(d.interpretation)}</p><small>منبع امتیاز: پاسخ‌های خوداظهاری؛ ${n(d.evidence.length)} گویه.</small>${d.strength_detail?`<p>رفتار قوی‌تر در پاسخ‌های شما: ${esc(d.strength_detail)}</p><p>رفتار نیازمند توجه بیشتر: ${esc(d.gap_detail)}</p><p>قدم پیشنهادی: ${esc(d.immediate)}</p>`:''}</article>`).join('')}</div><section><h2>هویت و جایگاه</h2><h3>پیشنهاد اولیهٔ پیام مرکزی</h3><p>${esc(report.central_message)}</p><p>مخاطب: ${esc(report.professional.audience)}</p><p>مسئله: ${esc(report.professional.problem)}</p><p>فرصت تمایز خوداظهارشده: ${esc(report.identity.difference)}</p><p>جایگاه مطلوب: ${esc(report.identity.remember)}</p><p>فاصلهٔ قابل اقدام: پیام معرفی پیشنهادی را با «${esc(report.identity.remember)}» مقایسه کنید و یک نمونهٔ واقعی برای ادعای تمایز خود اضافه کنید.</p></section>${report.content_evidence?`<section><h2>شواهد محتوا و اجرای دیجیتال</h2><p>موضوع‌های واردشده: ${esc(report.content_evidence.topics||'وارد نشده')}</p><p>نمونهٔ موردافتخار: ${esc(report.content_evidence.proud_content||'وارد نشده')}</p><p>نمونهٔ نیازمند بازنگری: ${esc(report.content_evidence.weak_content||'وارد نشده')}</p><p>این بخش شواهد واردشدهٔ خود شماست؛ بدون دریافت محتوای کافی، کیفیت لحن یا انسجام محتوا تأیید نمی‌شود.</p></section>`:''}${ig?`<section><h2>شواهد رسمی پیج</h2><p>آخرین همگام‌سازی: ${date(ig.synced_at)}</p><h3>متن معرفی دریافت‌شده</h3><p>${esc(ig.profile.biography||'این فیلد توسط API در دسترس نبود؛ جعل نشده است.')}</p><p>${n(ig.observations.sample_size)} محتوا و ${n(ig.observations.caption_count)} کپشن بررسی شد.</p><p>در ${n(ig.observations.possible_cta_count)} کپشن، واژه‌های احتمالی دعوت به اقدام دیده شد؛ این شمارش نشانهٔ کیفیت یا اثربخشی قطعی نیست.</p><p>قالب‌ها: ${Object.entries(ig.observations.formats).map(([k,v])=>`${esc(({IMAGE:'تصویر',VIDEO:'ویدیو',CAROUSEL_ALBUM:'آلبوم'})[k]||'سایر')} ${n(v)}`).join('، ')}</p><p>هشتگ‌های تکرارشونده: ${ig.observations.hashtags.map(v=>esc(v[0])).join('، ')||'نمونه‌ای ثبت نشده'}</p><p>این موضوع‌ها را با مخاطب و مسئلهٔ ادعاشدهٔ بالا مقایسه کنید؛ تطابق معنایی خودکار یا قضاوت شخصیت انجام نشده است.</p></section>`:''}<section><h2>سه اقدام فوری</h2>${list(report.immediate)}<h2>برنامهٔ سی روز آینده</h2>${list(report.thirty_days)}<p>شاخص‌های پیگیری: تعداد نمونه‌کار مستند، استمرار انتشار و اقدام مرتبط مخاطبان.</p></section><section><h2>محدودیت تحلیل</h2><ul>${report.limitations.map(v=>`<li>${esc(v)}</li>`).join('')}</ul><p>لینک عمومی ساخته نمی‌شود؛ در صورت دریافت فایل گزارش، فقط آن را با افراد مورداعتماد به اشتراک بگذارید.</p></section>`;
  }
  function comparison(first,second){return `<section><h2>مقایسهٔ دو نتیجه</h2><p>${first.template_version===second.template_version?'نسخهٔ تست یکسان است؛ تغییر نمره به‌تنهایی نشان‌دهندهٔ تغییر واقعی یا معناداری آماری نیست.':'نسخه‌های تست متفاوت‌اند؛ نمره‌ها ممکن است مستقیماً قابل مقایسه نباشند.'}</p>${first.dimensions.map(d=>`<p>${esc(d.title)}: ${n(d.score)} ← ${n(second.dimensions.find(v=>v.key===d.key)?.score)}</p>`).join('')}</section>`;}
  function paintReports(){
    const reports=current.reports;
    $('app').innerHTML=reports.length?reportView(reports[0].body):'<section><h2>گزارشی موجود نیست</h2><p>دادهٔ اینستاگرام یا گزارش قبلاً حذف شده است؛ برای تولید مجدد، ارزیابی تازه بسازید.</p></section>';
    if(reports.length>1&&reports[0].body.dimensions)$('app').insertAdjacentHTML('beforeend',`<section><h2>مقایسهٔ آخرین دو نسخه</h2>${reports[0].body.dimensions.map((d,i)=>`<p>${esc(d.title)}: ${n(reports[1].body.dimensions[i].score)} ← ${n(d.score)}</p>`).join('')}</section>`);
    if(current.template.schema!==4)$('app').insertAdjacentHTML('beforeend',connectionPanel());
    $('app').insertAdjacentHTML('beforeend',actions(button('home','بازگشت')+button('edit','انجام دوبارهٔ ارزیابی',current.assessment.id)+(current.report_unlocked&&reports.length?button('export_report','دریافت گزارش'):'')));
  }
  function paintAdmin(){
    const data=bootstrap;
    $('app').innerHTML=`<section id="assessments"><h2>مدیریت ارزیابی پرسونال برند</h2><nav aria-label="بخش‌های مدیریت ارزیابی">${[['assessments','ارزیابی‌ها'],['test-versions','نسخه‌های تست و سؤال‌ها'],['scoring-models','مدل نمره‌دهی'],['instagram-connections','اتصال‌های اینستاگرام'],['sync-status','همگام‌سازی و خطاها'],['privacy-settings','حریم خصوصی'],['validation','اعتبارسنجی']].map(([id,label])=>`<a href="#${id}">${label}</a>`).join('')}</nav><p>این ارزیابی مسیر اصلی سایت است. ارزیابی‌های قدیمی برای حفظ تاریخچه حذف نشده‌اند؛ فهرست زیر داده‌های واقعی ماژول نسخه‌دار را نشان می‌دهد.</p><h3>ارزیابی‌ها</h3><form id="admin-filter"><div class="grid"><label>شمارهٔ موبایل یا شناسهٔ ارزیابی<input name="search" type="search"></label><label>وضعیت<select name="state"><option value="">همه</option><option value="draft">پیش‌نویس</option><option value="completed">تکمیل‌شده</option></select></label><label>مرحلهٔ بلوغ<select name="maturity"><option value="">همه</option>${['شروع مسیر','در حال شکل‌گرفتن','قابل‌تشخیص','روبه‌رشد','جاافتاده و قابل‌اعتماد','کشف','تعریف','تثبیت','تمایز','مرجعیت'].map(v=>`<option>${v}</option>`).join('')}</select></label><label>اطمینان<select name="confidence"><option value="">همه</option><option>خوداظهاری</option><option>خوداظهاری به‌همراه شواهد</option></select></label><label>شواهد اینستاگرام در گزارش<select name="connected"><option value="">همه</option><option value="yes">دارد</option><option value="no">ندارد</option></select></label></div><button>اعمال فیلتر</button></form><p>تعداد کل در این فیلتر: ${n(data.total)} · صفحهٔ ${n(data.offset/100+1)}</p>${actions((data.offset>0?button('page_previous','صفحهٔ قبل'):'')+(data.offset+100<data.total?button('page_next','صفحهٔ بعد'):''))}<label>جست‌وجو در صفحهٔ دریافت‌شده<input id="filter" type="search"></label><div id="assessment-list">${data.assessments.length?data.assessments.map((r,i)=>`<p data-row>${n(i+1)} · ${date(r.created_at)} · ${r.state==='completed'?'تکمیل‌شده':'پیش‌نویس'} ${r.archived_at?'· آرشیو':''}<small>بلوغ: ${esc(r.maturity||'هنوز محاسبه نشده')} · اطمینان: ${esc(r.confidence||'هنوز محاسبه نشده')}</small><small>مرحله: ${n(r.stage)} از ۵ · نسخهٔ تست: ${esc(r.template_version)} · نسخهٔ موتور: ${esc(r.scoring_version)}</small><small>تحلیل: ${esc(({running:'در حال اجرا',success:'تولیدشده',failed:'نیازمند رسیدگی'})[r.analysis_status]||'هنوز اجرا نشده')} · اینستاگرام: ${esc(({connected:'متصل',expired:'مجوز منقضی',disconnected:'قطع‌شده'})[r.instagram_status]||'متصل نیست')} · پایان: ${r.completed_at?date(r.completed_at):'تکمیل نشده'}</small><small>لید: ${r.lead_status==='registered'?'ثبت‌شده':'ثبت نشده'}</small><small>شناسه: <bdi>${esc(r.id)}</bdi></small> ${button('admin_open','مشاهدهٔ پاسخ و نتیجه',r.id)}</p>`).join(''):'<p>هنوز ارزیابی واقعی در این ماژول ثبت نشده است.</p>'}</div></section><section id="test-versions"><h2>نسخه‌های تست و سؤال‌ها</h2>${data.templates.map(t=>`<details><summary>نسخهٔ ${n(t.version)} · ${esc(t.status==='published'?'منتشرشده':t.status==='draft'?'پیش‌نویس':'غیرفعال')}</summary>${(t.body.items||t.body.behavior||[]).map(q=>`<p>${esc(q.title)}</p>`).join('')}${actions(button('template_edit','ساخت نسخهٔ اصلاحی',t.id)+button('template_publish','انتشار یا بازگردانی به این نسخه',t.id)+button('template_inactive','غیرفعال‌سازی',t.id)+button('feedback','ثبت بازخورد خبره',t.id))}</details>`).join('')}</section><section id="scoring-models"><h2>مدل نمره‌دهی</h2>${data.models.map(m=>`<p>نسخهٔ ${n(m.version)} · ${esc(m.status==='published'?'منتشرشده':m.status==='draft'?'پیش‌نویس':'غیرفعال')}</p>${actions(button('model_edit','نسخهٔ جدید وزن‌ها',m.id)+button('model_publish','انتشار یا بازگردانی',m.id))}`).join('')}</section><section id="instagram-connections"><h2>اتصال‌های اینستاگرام و همگام‌سازی</h2>${data.connections.length?data.connections.map(c=>`<p>${esc(c.username)} · ${esc(c.status==='connected'?'متصل':c.status==='expired'?'منقضی':'قطع‌شده')} · آخرین همگام‌سازی ${c.synced_at?date(c.synced_at):'ندارد'}${button('disconnect_connection','قطع اتصال با ثبت دلیل',c.id)}</p>`).join(''):'<p>هیچ اتصال ثبت‌شده‌ای نیست.</p>'}<p>تعداد خطاهای همگام‌سازی در ۱۰۰ اجرای اخیر: ${n(data.sync_jobs.filter(j=>j.status==='failed').length)}</p></section><section id="sync-status"><h2>وضعیت همگام‌سازی و خطاهای پردازش</h2>${data.sync_jobs.length?`<div class="scroll"><table><thead><tr><th>زمان</th><th>وضعیت</th><th>خطا</th></tr></thead><tbody>${data.sync_jobs.map(j=>`<tr><td>${date(j.created_at)}</td><td>${esc(({running:'در حال اجرا',success:'موفق',failed:'ناموفق'})[j.status]||'ثبت‌شده')}</td><td>${j.error_code?'سرویس موقتاً در دسترس نبود؛ دوباره تلاش کنید.':'ندارد'}</td></tr>`).join('')}</tbody></table></div>`:'<p>همگام‌سازی ثبت نشده است.</p>'}</section><section id="privacy-settings"><h2>حریم خصوصی و نگهداری داده</h2><form id="privacy-form"><label>روز نگهداری snapshot اینستاگرام<input name="days" type="number" min="1" max="365" value="${data.retention_days}" required></label><label>دلیل تغییر<textarea name="reason" required maxlength="500"></textarea></label><button>ثبت سیاست</button></form></section><section><h2>اعتبارسنجی تدریجی</h2><p>ابزار هنوز از نظر آماری تأیید نشده است. زمان کل مرحله و زمان تمرکز روی گویه‌ها از مرورگر دریافت می‌شود؛ این زمان‌ها زمان دقیق تفکر نیستند.</p>${data.metrics.map(m=>`<p>مرحلهٔ ${n(m.step)}: ${n(m.completed)} ثبت، میانگین زمان ${n(Math.round(m.elapsed_ms/1000))} ثانیه</p>`).join('')||'<p>پاسخ واقعی برای محاسبه وجود ندارد.</p>'}</section>`;
    $('app').insertAdjacentHTML('beforeend',`<section id="validation"><h2>داده‌های مقدماتی اعتبارسنجی</h2>${data.validation.map(v=>`<details><summary>نسخهٔ ${n(data.templates.find(t=>t.id===v.template_version)?.version)} · ${n(v.sample_size)} پاسخ</summary><p>${esc(v.warning)}</p><p>پاسخ‌های یکنواخت: ${n(v.straight_line_count)}</p>${v.internal_consistency.map(d=>`<p>ثبات درونی ${esc(dimensionTitle(d.dimension))}: ${d.alpha===null?'قابل محاسبه نیست':n(d.alpha)}</p>`).join('')}${technical(v.correlations)}${data.permissions.export?button('validation_export','دریافت پاسخ‌های عددی ناشناس',v.template_version):''}</details>`).join('')}<h3>زمان تمرکز ثبت‌شدهٔ گویه‌ها</h3>${data.question_metrics.map(m=>`<p>${esc((data.templates[0].body.items||data.templates[0].body.behavior||[]).find(q=>q.id===m.question_id)?.title||'گویه')}: ${n(Math.round(m.elapsed_ms/1000))} ثانیه، ${n(m.measured)} اندازه‌گیری</p>`).join('')||'<p>هنوز اندازه‌گیری ثبت نشده است.</p>'}</section>`);
    $('app').insertAdjacentHTML('beforeend',`<section><h2>بازخورد وضوح سؤال‌ها</h2>${(data.question_feedback||[]).map(f=>`<p>${esc((data.templates.find(t=>t.id===f.template_version)?.body.behavior||[]).find(q=>q.id===f.question_id)?.title||f.question_id)}: ${n(f.clarity)} از ۳ · ${n(f.responses)} بازخورد</p>`).join('')||'<p>هنوز بازخوردی ثبت نشده است.</p>'}<h3>بازبینی‌های تخصصی ثبت‌شده</h3>${(data.feedback||[]).map(f=>`<details><summary>${date(f.created_at)}</summary><pre>${esc(f.body)}</pre></details>`).join('')||'<p>هنوز بازبینی ثبت نشده است.</p>'}</section>`);
    if(data.permissions.private)$('app').insertAdjacentHTML('beforeend',`<section><h2>مقایسهٔ دو ارزیابی</h2><form id="compare-assessments"><label>شناسهٔ ارزیابی اول<input name="first" maxlength="36" required></label><label>شناسهٔ ارزیابی دوم<input name="second" maxlength="36" required></label><button>مقایسهٔ آخرین گزارش‌ها</button></form><div id="comparison"></div></section>`);
    if(!data.permissions.manage)$('privacy-form').replaceWith(Object.assign(document.createElement('p'),{textContent:'تغییر سیاست نگهداری فقط برای مدیر مجاز است.'}));
  }
  async function open(id){skipping=false;questionTimes={};focusedQuestion=null;current=await api('?id='+encodeURIComponent(id));step=Math.min(current.assessment.stage+1,5);if(current.assessment.state==='completed'){paintReports();await api('',{action:'view_report',id});}else paintStep();}
  document.addEventListener('input',event=>{
    if(event.target.id==='filter'){for(const row of document.querySelectorAll('[data-row]'))row.hidden=!row.textContent.includes(event.target.value);return;}
    const form=event.target.closest('#step-form');if(!form||!current)return;
    if(['barrier','audience'].includes(event.target.name)&&form.querySelectorAll(`input[name="${event.target.name}"]:checked`).length>2){event.target.checked=false;$('feedback').textContent='حداکثر دو گزینه را انتخاب کن.';return;}
    if(current.template.schema===4&&event.target.name==='available_proof'&&event.target.checked){for(const input of form.querySelectorAll('input[name="available_proof"]')){if(input!==event.target&&(event.target.value==='هنوز چیز مشخصی ندارم'||input.value==='هنوز چیز مشخصی ندارم'))input.checked=false;}}
    if([3,4].includes(current.template.schema)){if(current.template.schema===3)updateOtherFields(form);else updateV4Other(form);persistDraft(form);return;}
    const values=formValues(form);try{localStorage.setItem('pb-draft-'+current.assessment.id+'-'+step,JSON.stringify(values));if($('save-state'))$('save-state').textContent='پاسخ‌هایت ذخیره شده و می‌توانی بعداً ادامه بدهی.';}catch{$('feedback').textContent='پاسخ‌هایت با زدن «ادامه» ذخیره می‌شود.';}
    const count=form.querySelector(`[data-count="${event.target.name}"]`);if(count)count.textContent=n(event.target.value.length)+' از '+n(event.target.maxLength)+' نویسه';
  });
  document.addEventListener('submit',async event=>{
    if(event.target.closest('#confirm'))return;event.preventDefault();if(busy)return;busy=true;
    const form=event.target,submitter=event.submitter,buttons=[...form.querySelectorAll('button')].map(button=>[button,button.disabled]);for(const [button] of buttons)button.disabled=true;
    try{
      const values=formValues(form);
      if(form.id==='question-feedback'){
        await api('',{action:'question_feedback',id:current.assessment.id,question_id:values.question_id,clarity:Number(values.clarity)});
      }else if(form.id==='expert-review'){
        const rubric=Object.fromEntries(['fit','clarity','nonjudgment','unambiguous','distinct'].map(key=>[key,Number(values[key])]));
        await api('',{action:'feedback',id:form.dataset.id,question_id:values.question_id,rubric,reason:values.reason,confirmed:true});await load();
      }else if(form.id==='lead-form'){
        const values=Object.fromEntries(new FormData(form));
        await api('',{action:'unlock_report',id:current.assessment.id,phone:values.phone,consent:values.consent==='on'});
        await open(current.assessment.id);
      }else if(form.id==='step-form'){
        await flushDraft();
        finishFocus();
        if(step===3)for(const key in values)values[key]=Number(values[key]);
        let answers=values;
        if(step===5&&current.template.schema!==4)answers={...values,choice:submitter?.name==='connected'?'connected':'skip'};
        const id=current.assessment.id;
        const saved=await api('',{action:'save',id,revision:current.assessment.revision,step,answers,question_times:step===3?questionTimes:{},elapsed_ms:Math.min(Date.now()-started,86400000)});
        current.assessment.revision=saved.revision;current.answers[String(step)]=answers;try{localStorage.removeItem('pb-draft-'+id+'-'+step);}catch{}
        if(step===5){await api('',{action:'report',id});await open(id);}else{step++;paintStep();}
      }else if(form.id==='compare-assessments'){
        const [first,second]=await Promise.all([api('?id='+encodeURIComponent(values.first)),api('?id='+encodeURIComponent(values.second))]);
        if(!first.reports.length||!second.reports.length)throw new Error('هر دو ارزیابی باید گزارش موجود داشته باشند.');
        $('comparison').innerHTML=comparison(first.reports[0].body,second.reports[0].body);
      }else if(form.id==='compare-versions'){
        const first=current.reports.find(r=>r.id===values.first),second=current.reports.find(r=>r.id===values.second);
        if(!first||!second)throw new Error('نسخه‌های نتیجه را انتخاب کنید.');
        $('comparison').innerHTML=comparison(first.body,second.body);
      }else if(form.id==='admin-filter'){
        adminQuery=values;bootstrap=await api('?'+new URLSearchParams(values));paintAdmin();
      }else if(form.id==='template-form'||form.id==='model-form'){
        const kind=form.id==='template-form'?'template':'model',version=bootstrap[kind==='template'?'templates':'models'].find(v=>v.id===form.dataset.id),body=JSON.parse(JSON.stringify(version.body));
        if(kind==='template')for(const q of (body.items||body.behavior)){q.title=values[q.id];q.order=Number(values[q.id+'_order']);q.active=values[q.id+'_active']==='true';}else for(const k of Object.keys(body.dimensions))body.dimensions[k]=Number(values[k]);
        if(await confirmAction('نسخهٔ پیش‌نویس مستقل ساخته می‌شود؛ نسخه‌های قبلی تغییر نمی‌کنند.')){await api('',{action:kind+'_draft',body,reason:values.reason,confirmed:true});await load();}else throw new Error('عملیات به انتخاب شما لغو شد.');
      }else if(form.id==='privacy-form'){if(!await confirmAction('سیاست نگهداری برای پاک‌سازی‌های بعدی اعمال می‌شود.'))throw new Error('عملیات به انتخاب شما لغو شد.');await api('',{action:'privacy',retention_days:Number(values.days),reason:values.reason,confirmed:true});await load();}
      $('feedback').textContent='پاسخ‌هایت ذخیره شد؛ هر وقت آماده بودی ادامه بده.';
    }catch(error){if(form.id==='lead-form'){$('lead-error').textContent=error.message;form.querySelector?.('[name=phone]')?.setAttribute('aria-invalid','true');}else $('feedback').textContent=error.message;}finally{busy=false;for(const [button,disabled] of buttons)button.disabled=disabled;}
  });
  document.addEventListener('click',async event=>{
    const target=event.target.closest('[data-action]');if(!target||busy)return;busy=true;target.disabled=true;
    const action=target.dataset.action,id=target.dataset.id;
    try{
      if(action==='start'){const row=await api('',{action});await open(row.id);}
      else if(action==='edit'){if(await confirmAction('یک ارزیابی تازه شروع می‌شود و نتیجهٔ قبلی‌ات حفظ می‌شود.')){const row=await api('',{action:'restart',id:current.assessment.id,confirmed:true});await open(row.id);}}
      else if(action==='open')await open(id);
      else if(action==='page_next'||action==='page_previous'){adminQuery.offset=Math.max(0,bootstrap.offset+(action==='page_next'?100:-100));bootstrap=await api('?'+new URLSearchParams(adminQuery));paintAdmin();}
      else if(action==='export_report'){const result=await api('',{action,id:current.assessment.id});const content='<!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'"><title>گزارش ارزیابی پرسونال برند</title><style>body{font:16px/2 Tahoma,sans-serif;max-width:900px;margin:auto;padding:24px;color:#203d30}section,article{border:1px solid #ccd8cc;border-radius:12px;padding:20px;margin:16px 0}progress{width:100%}p,li{white-space:pre-wrap;overflow-wrap:anywhere}small{display:block}</style>'+reportView(result.report)+'</html>';const url=URL.createObjectURL(new Blob([content],{type:'text/html;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='personal-brand-report.html';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
      else if(action==='validation_export'){const result=await api('?action=validation_export&template_version='+encodeURIComponent(id));const url=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='anonymous-assessment-responses.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
      else if(action==='skip'){skipping=true;paintStep();}
      else if(action==='later'){target.textContent='هر وقت آماده بودی شماره‌ات را وارد کن';target.disabled=true;}
      else if(action==='previous'){await flushDraft();step--;paintStep();}
      else if(action==='home'){await flushDraft();if(!admin && current?.assessment.state==='draft')await api('',{action:'abandon',id:current.assessment.id});await load();}
      else if(action==='oauth'){if(current?.template?.schema===3){if(!$('consent').checked)throw new Error('برای اتصال، رضایتت را تأیید کن.');await flushDraft();const r=await api('',{action,consent:true,id:current.assessment.id});location.assign(r.authorization_url);}else{if(!$('consent').checked)throw new Error('برای اتصال، رضایت آگاهانه را انتخاب کنید.');const r=await api('',{action,consent:true});location.assign(r.authorization_url);}}
      else if(action==='sync'){await api('',{action});bootstrap=await api('?action=bootstrap');if(current)paintStep();else home();}
      else if(['disconnect','delete_instagram','delete_assessment'].includes(action)){if(await confirmAction(action==='disconnect'?'استفادهٔ آینده از مجوز متوقف می‌شود.':'داده و گزارش‌های مربوط حذف می‌شوند؛ این عملیات برگشت‌پذیر نیست.')){await api('',{action,id:current?.assessment.id});if(action==='delete_assessment'){for(let s=1;s<=5;s++){try{localStorage.removeItem('pb-draft-'+current.assessment.id+'-'+s);}catch{}}}await load();}}
      else if(action==='admin_open'){current=await api('?id='+encodeURIComponent(id));$('app').innerHTML=`${button('home','بازگشت')}<nav class="analysis-tabs">${[['detail-summary','خلاصه'],['detail-answers','پاسخ‌ها'],['detail-results','نمره‌ها و نتیجه'],['detail-evidence','شواهد'],['detail-instagram','اینستاگرام'],['detail-runs','تاریخچهٔ تحلیل و خطاها']].map(([key,title])=>`<a href="#${key}">${title}</a>`).join('')}</nav><section id="detail-summary"><h2>خلاصهٔ ارزیابی</h2>${current.lead?`<p>شمارهٔ ثبت‌شده با رضایت: <bdi>${esc(current.lead.phone)}</bdi> · ${date(current.lead.created_at)}</p>`:'<p>شماره ثبت نشده است.</p>'}<p>نسخهٔ تست: ${esc(current.assessment.template_version)} · مدل: ${esc(current.assessment.scoring_version)}</p><p>شروع: ${date(current.assessment.created_at)} · مرحلهٔ ${n(current.assessment.stage)} از ۵</p></section><section id="detail-answers"><h2>پاسخ‌های ارزیابی</h2>${Object.entries(current.answers).map(([s,values])=>`<h3>مرحلهٔ ${n(s)}</h3><dl>${Object.entries(values).map(([key,value])=>`<dt>${esc((current.template.items||current.template.behavior||[]).find(q=>q.id===key)?.title||[...(current.template.base||[]),...(current.template.identity||current.template.image||[]),...(current.template.evidence||[]),...(current.template.online||[])].find(f=>f[0]===key)?.[1]||({goal:'هدف برند',choice:'روش اتصال',introduction:'معرفی اختیاری'})[key]||'پاسخ')}</dt><dd>${esc(s==='3'?current.template.likert[Number(value)-1]:value==='skip'?'بدون اتصال':value==='connected'?'همراه اتصال':value)}</dd>`).join('')}</dl>`).join('')}</section><div id="detail-results">${current.reports.map(r=>reportView(r.body)).join('')||'<p>نتیجه هنوز تولید نشده است.</p>'}</div><section id="detail-evidence"><h2>شواهد واردشده</h2>${current.template.evidence.map(([key,title])=>`<h3>${esc(title)}</h3><p>${esc(current.answers['4']?.[key]||'ثبت نشده')}</p>`).join('')}</section><section id="detail-instagram"><h2>وضعیت اینستاگرام</h2><p>${current.connection?esc(current.connection.username)+' · '+esc(({connected:'متصل',expired:'منقضی',disconnected:'قطع‌شده'})[current.connection.status]):'متصل نیست'}</p>${current.instagram?technical(current.instagram):'<p>snapshot مجاز همگام‌شده موجود نیست.</p>'}</section><section id="detail-runs"><h2>تاریخچهٔ تحلیل و خطاها</h2>${(current.analysis_runs||[]).map(r=>`<p>${date(r.created_at)} · ${esc(r.engine_version)} · ${esc(({running:'در حال اجرا',success:'موفق',failed:'ناموفق'})[r.status])}${r.error_code?' · پاسخ‌ها ناقص یا نامعتبر بوده‌اند؛ مراحل را بررسی کنید.':''}</p>`).join('')||'<p>اجرای جدیدی ثبت نشده است.</p>'}<h3>رویدادهای حسابرسی</h3>${(current.audit||[]).map(r=>`<p>${date(r.created_at)} · ${esc(r.action)}</p>`).join('')}</section>${bootstrap.permissions.private?technical(current):''}${actions(button('regenerate','تولید نسخهٔ جدید نتیجه',id)+button('archive','آرشیو نرم',id)+button('erase_assessment','حذف واقعی بنا به درخواست صاحب داده',id))}`;if(current.reports.length>1)$('app').insertAdjacentHTML('beforeend',`<section><h2>مقایسهٔ نسخه‌های نتیجه</h2><form id="compare-versions">${['first','second'].map((key,index)=>`<label>نتیجهٔ ${n(index+1)}<select name="${key}">${current.reports.map((r,i)=>`<option value="${esc(r.id)}" ${i===index?'selected':''}>نسخهٔ ${n(r.version)}</option>`).join('')}</select></label>`).join('')}<button>مقایسه</button></form><div id="comparison"></div></section>`);}
      else if(action==='feedback'){
        const version=bootstrap.templates.find(v=>v.id===id);
        $('app').innerHTML=`<section><h2>بازبینی تخصصی سؤال</h2><form id="expert-review" data-id="${esc(id)}"><label>سؤال<select name="question_id">${(version.body.items||version.body.behavior).map(q=>`<option value="${esc(q.id)}">${esc(q.title)}</option>`).join('')}</select></label>${[['fit','تناسب با بُعد'],['clarity','وضوح سؤال'],['nonjudgment','نبود قضاوت ارزشی'],['unambiguous','نبود ابهام'],['distinct','نبود هم‌پوشانی زیاد']].map(([key,title])=>`<label>${title}<select name="${key}"><option value="1">نیازمند بازنگری</option><option value="2">تا حدی مناسب</option><option value="3">مناسب</option></select></label>`).join('')}<label>توضیح و دلیل<textarea name="reason" maxlength="500" required></textarea></label><button>ثبت بازبینی</button></form></section>`;
      }
      else if(action==='template_edit'||action==='model_edit'){
        const kind=action==='template_edit'?'template':'model',v=bootstrap[kind==='template'?'templates':'models'].find(v=>v.id===id);
        if(kind==='template'&&!v.body.statuses&&!v.body.schema)throw new Error('این نسخه برای ویرایش در دسترس نیست.');
        $('app').innerHTML=`<section><h2>نسخهٔ جدید؛ بدون تغییر نسخهٔ قبلی</h2><form id="${kind}-form" data-id="${id}">${kind==='template'?(v.body.items||v.body.behavior||[]).map(q=>field(q.id,q.title,q.title,true)+`<div class="grid"><label>ترتیب (۰ تا ${n((v.body.items||v.body.behavior).length-1)})<input name="${esc(q.id)}_order" type="number" min="0" max="${(v.body.items||v.body.behavior).length-1}" value="${q.order}" required></label><label>نمایش گویه<select name="${esc(q.id)}_active"><option value="true" ${q.active?'selected':''}>فعال</option>${v.body.schema===3?'':'<option value="false" '+(!q.active?'selected':'')+'>غیرفعال</option>'}</select></label></div>`).join(''):Object.entries(v.body.dimensions).map(([key,value])=>`<label>وزن ${esc(dimensionTitle(key))}<input type="number" name="${key}" value="${value}" min="0.001" max="1" step="any" required></label>`).join('')}<label>دلیل تغییر<textarea name="reason" maxlength="500" required></textarea></label><button>ثبت پیش‌نویس</button></form></section>`;
      }else if(admin){const reason=prompt('دلیل این عملیات را بنویسید:');if(reason&&await confirmAction('عملیات ثبت و حسابرسی می‌شود؛ تاریخچهٔ قبلی حفظ خواهد شد.')){await api('',{action,id,reason,confirmed:true,...(action==='regenerate'?{scoring_version:current?.assessment.scoring_version}:{})});await load();}}
    }catch(error){$('feedback').textContent=error.message;}finally{busy=false;target.disabled=false;}
  });
  $('retry')?.addEventListener('click',()=>load().catch(error=>$('feedback').textContent=error.message));
  load().catch(error=>{$('feedback').textContent=error.message;$('app').textContent='صفحه آماده نشد؛ چند لحظه بعد دوباره امتحان کن.';});
})();
